What does this program print?

```zig
var it = std.mem.splitScalar(u8, ",x,,y,", ',');
var n: usize = 0;
while (it.next()) |_| n += 1;
var tok = std.mem.tokenizeScalar(u8, ",x,,y,", ',');
var m: usize = 0;
while (tok.next()) |_| m += 1;
std.debug.print("{d} {d}\n", .{ n, m });
```

What does this program print?

```zig
const std = @import("std");

fn bump(xs: []u32) void {
    for (xs) |*x| x.* += 1;
}

fn bumpCopy(xs: [3]u32) void {
    var local = xs;
    for (&local) |*x| x.* += 100;
}

pub fn main() void {
    var data = [_]u32{ 1, 2, 3 };
    bump(data[1..]);
    bumpCopy(data);
    std.debug.print("{any}\n", .{data});
}
```
